INSERT INTO public.frases (texto, autor, ativo) VALUES
  ('A tristeza, mesmo quando justificada, muitas vezes é preguiça. Nada exige menos esforço do que estar triste.', 'Sêneca', true),
  ('Podemos julgar nosso progresso pela coragem de nossas perguntas e pela profundidade de nossas respostas, pela disposição de abraçar o que é verdadeiro em vez do que parece bom.', 'Carl Sagan', true),
  ('Seu jardim não está prosperando porque toda vez que uma flor nasce você a arranca pra provar para os outros que é um jardineiro.', 'Desconhecido', true),
  ('Não tropece em algo que já está atrás de você.', 'Sêneca', true),
  ('Amargas são as raízes do estudo, mas quão doces são seus frutos.', 'Catão', true),
  ('Apenas o ego se ofende. Quanto mais forte o ego, mais frágil será a pessoa, pois ficará mais suscetível de ser atingida pelas atitudes alheias. Diminua o tamanho do alvo e dificultará o trabalho das flechas.', 'Desconhecido', true),
  ('Quanto mais próximo o colapso de um império, mais insanas as suas leis.', 'Cícero', true),
  ('O propósito do conhecimento é a ação, não o conhecimento em si.', 'Aristóteles', true),
  ('A morte puxa minha orelha e diz: viva, estou chegando.', 'Virgílio', true),
  ('Quando estamos cansados, somos atacados por ideias que já conquistamos há muito tempo.', 'Nietzsche', true);
